class Solution:
    def tree2str(self, root) -> str:
        if root is None: return ""
        if root.left is None and root.right is None: return str(root.val)
        if root.right is None: return f"{root.val}({self.tree2str(root.left)})"
        return f"{root.val}({self.tree2str(root.left)})({self.tree2str(root.right)})"

class Solution {
 public String tree2str(TreeNode root){if(root==null)return "";if(root.left==null&&root.right==null)return Integer.toString(root.val);if(root.right==null)return root.val+"("+tree2str(root.left)+")";return root.val+"("+tree2str(root.left)+")("+tree2str(root.right)+")";}
}

from collections import defaultdict
class Solution:
 def findDuplicate(self,paths):
  groups=defaultdict(list)
  for desc in paths:
   parts=desc.split();directory=parts[0]
   for file in parts[1:]:
    name,content=file.split('(',1);groups[content[:-1]].append(directory+'/'+name)
  return [g for g in groups.values() if len(g)>1]

import java.util.*;
class Solution {
 public List<List<String>> findDuplicate(String[] paths){Map<String,List<String>>g=new HashMap<>();for(String desc:paths){String[]p=desc.split(" ");String dir=p[0];for(int i=1;i<p.length;i++){String f=p[i];int at=f.indexOf('(');String content=f.substring(at+1,f.length()-1);g.computeIfAbsent(content,k->new ArrayList<>()).add(dir+"/"+f.substring(0,at));}}List<List<String>>out=new ArrayList<>();for(List<String>x:g.values())if(x.size()>1)out.add(x);return out;}
}

class Solution:
 def triangleNumber(self,nums):
  nums.sort();ans=0
  for k in range(len(nums)-1,1,-1):
   i,j=0,k-1
   while i<j:
    if nums[i]+nums[j]>nums[k]:ans+=j-i;j-=1
    else:i+=1
  return ans

import java.util.*;
class Solution {
 public int triangleNumber(int[]a){Arrays.sort(a);int ans=0;for(int k=a.length-1;k>=2;k--){int i=0,j=k-1;while(i<j){if(a[i]+a[j]>a[k]){ans+=j-i;j--;}else i++;}}return ans;}
}

class Solution:
 def mergeTrees(self,a,b):
  if a is None:return b
  if b is None:return a
  a.val+=b.val;a.left=self.mergeTrees(a.left,b.left);a.right=self.mergeTrees(a.right,b.right);return a

class Solution {
 public TreeNode mergeTrees(TreeNode a,TreeNode b){if(a==null)return b;if(b==null)return a;a.val+=b.val;a.left=mergeTrees(a.left,b.left);a.right=mergeTrees(a.right,b.right);return a;}
}

from collections import Counter
class Solution:
 def leastInterval(self,tasks,n):
  f=Counter(tasks);high=max(f.values());tied=sum(v==high for v in f.values())
  return max(len(tasks),(high-1)*(n+1)+tied)

class Solution {
 public int leastInterval(char[]tasks,int n){int[]f=new int[26];int high=0;for(char t:tasks)high=Math.max(high,++f[t-'A']);int tied=0;for(int x:f)if(x==high)tied++;return Math.max(tasks.length,(high-1)*(n+1)+tied);}
}

class Solution:
 def addOneRow(self,root,val,depth):
  if depth==1:
   r=TreeNode(val);r.left=root;return r
  if root is None:return None
  stack=[(root,1)]
  while stack:
   node,d=stack.pop()
   if d==depth-1:
    left=TreeNode(val);right=TreeNode(val);left.left=node.left;right.right=node.right;node.left,node.right=left,right
   else:
    if node.right:stack.append((node.right,d+1))
    if node.left:stack.append((node.left,d+1))
  return root

class Solution {
 public TreeNode addOneRow(TreeNode root,int val,int depth){if(depth==1){TreeNode r=new TreeNode(val);r.left=root;return r;}if(root==null)return null;java.util.ArrayDeque<TreeNode>q=new java.util.ArrayDeque<>();q.add(root);int d=1;while(!q.isEmpty()&&d<depth-1){int size=q.size();for(int i=0;i<size;i++){TreeNode x=q.remove();if(x.left!=null)q.add(x.left);if(x.right!=null)q.add(x.right);}d++;}if(d==depth-1)while(!q.isEmpty()){TreeNode x=q.remove(),l=new TreeNode(val),r=new TreeNode(val);l.left=x.left;r.right=x.right;x.left=l;x.right=r;}return root;}
}

