from collections import deque
class Solution:
 def averageOfLevels(self,root):
  if root is None:return []
  q=deque([root]);out=[]
  while q:
   total=0;size=len(q)
   for _ in range(size):
    x=q.popleft();total+=x.val
    if x.left:q.append(x.left)
    if x.right:q.append(x.right)
   out.append(total/size)
  return out

import java.util.*;
class Solution {
 public List<Double> averageOfLevels(TreeNode root){List<Double>out=new ArrayList<>();if(root==null)return out;Queue<TreeNode>q=new ArrayDeque<>();q.add(root);while(!q.isEmpty()){int size=q.size();double sum=0;for(int i=0;i<size;i++){TreeNode x=q.remove();sum+=x.val;if(x.left!=null)q.add(x.left);if(x.right!=null)q.add(x.right);}out.add(sum/size);}return out;}
}

class Solution:
 def findMaxAverage(self,nums,k):
  total=sum(nums[:k]);best=total
  for i in range(k,len(nums)):total+=nums[i]-nums[i-k];best=max(best,total)
  return best/k

class Solution {
 public double findMaxAverage(int[]a,int k){int sum=0;for(int i=0;i<k;i++)sum+=a[i];int best=sum;for(int i=k;i<a.length;i++){sum+=a[i]-a[i-k];best=Math.max(best,sum);}return (double)best/k;}
}

class Solution:
 def findErrorNums(self,nums):
  seen=set();duplicate=0
  for x in nums:
   if x in seen:duplicate=x
   seen.add(x)
  missing=next(x for x in range(1,len(nums)+1) if x not in seen)
  return [duplicate,missing]

class Solution {
 public int[] findErrorNums(int[]a){boolean[]seen=new boolean[a.length+1];int dup=0;for(int x:a){if(seen[x])dup=x;seen[x]=true;}for(int x=1;x<seen.length;x++)if(!seen[x])return new int[]{dup,x};return new int[0];}
}
